<script setup>
import ProjectDescription from './ProjectDescription.vue'
import {projectPublicPath} from './project-address.js'
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {call,client,labels} from './pms-client.js'
import {watchAdminChanges} from './change-events.js'
import {projectManageUrl,projectStatusLabel} from './project-admin.js'
const rows=ref([]),error=ref(''),loading=ref(true),search=ref(''),status=ref('');let stopChanges,epoch=0,disposed=false
const shown=computed(()=>{const query=search.value.trim().toLocaleLowerCase();return rows.value.filter(p=>(!status.value||p.status===status.value)&&(!query||[p.title,p.customer,p.slug,p.description].some(v=>String(v||'').toLocaleLowerCase().includes(query))))})
async function load(){const id=++epoch;loading.value=true;try{const data=await call('pms_catalog');if(disposed||id!==epoch)return;rows.value=data;error.value=''}catch{if(id===epoch&&!disposed)error.value='사이트 목록 확인에 실패했습니다.'}finally{if(id===epoch&&!disposed)loading.value=false}}
onMounted(()=>{load();stopChanges=watchAdminChanges(client(),['projects'],load)})
onUnmounted(()=>{disposed=true;++epoch;stopChanges?.()})
</script>
<template><main class="member-page"><h1>Project Online 사이트 현황</h1><p>새로 등록한 초안부터 게시·보관 프로젝트까지 확인하고 관리합니다.</p><div class="site-toolbar"><label>프로젝트 검색<input v-model="search" placeholder="프로젝트명, 기업·기관, 주소 이름"></label><label>운영 상태<select v-model="status"><option value="">전체</option><option value="draft">초안</option><option value="published">게시</option><option value="archived">보관</option></select></label><button :disabled="loading" @click="load">목록 새로고침</button><a href="/admin/#projects?new=1">새 프로젝트 등록</a></div><p v-if="loading" role="status">사이트 목록을 불러오고 있습니다.</p><p v-if="error" role="alert">{{error}} <button @click="load">다시 확인</button></p><p v-if="!loading&&!error" role="status">전체 {{rows.length}}개 · 표시 {{shown.length}}개</p><div class="admin-site-cards"><article v-for="p in shown" :key="p.slug" :data-project="p.slug"><div class="site-card-heading"><span>{{p.customer||'기업·기관 미입력'}}</span><strong class="site-state">{{projectStatusLabel(p.status)}}</strong></div><h2>{{p.title}}</h2><ProjectDescription :text="p.description"/><p>{{labels[p.access_mode]}}</p><p class="site-address">{{projectPublicPath(p.slug)}}</p><div class="site-actions"><a :href="projectManageUrl(p.slug)">프로젝트 관리</a><a v-if="p.status==='published'" :href="projectPublicPath(p.slug)" target="_blank" rel="noopener">사이트 열기 ↗</a></div><p v-if="p.status==='draft'" class="site-note">관리에서 원본·그룹 접근 권한과 배포 주소를 준비한 뒤 게시할 수 있습니다.</p><p v-else-if="p.status==='archived'" class="site-note">보관 중입니다. 관리에서 운영 상태를 변경할 수 있습니다.</p></article></div><p v-if="!loading&&!error&&!shown.length">{{rows.length?'조건에 맞는 프로젝트가 없습니다.':'등록된 프로젝트가 없습니다.'}}</p><a href="/admin/#projects">전체 프로젝트 설정 관리 →</a></main></template>
<style scoped>.site-toolbar{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:24px 0}.site-toolbar label{display:grid;gap:7px}.site-toolbar input,.site-toolbar select,.site-toolbar button,.site-toolbar>a{border:1px solid #b9c9da;border-radius:7px;padding:10px 12px;background:white}.site-toolbar input{min-width:240px}.admin-site-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px;margin:24px 0}.admin-site-cards article{border:1px solid #d5e0eb;border-radius:10px;padding:24px;overflow-wrap:anywhere}.admin-site-cards h2{font-size:21px;font-weight:700;margin:12px 0}.admin-site-cards p{margin:12px 0}.site-card-heading{display:flex;justify-content:space-between;gap:12px;font-size:13px}.site-state{border-radius:5px;background:#edf3fa;padding:3px 8px;white-space:nowrap}.site-actions{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.site-actions a{padding:10px 14px;border-radius:7px;background:#1c3e63;color:white}.site-address,.site-note{font-size:13px;color:#526a81}@media(max-width:480px){.site-toolbar label,.site-toolbar input{width:100%;min-width:0}}</style>
